-- Exact small data recipes from the 2026-09-20 research archive.
-- Distinct table prefix avoids overwriting the versioned profile fixtures.
CREATE TABLE {{schema}}.research_empty_table(id bigint PRIMARY KEY);
CREATE TABLE {{schema}}.research_single_row(id bigint PRIMARY KEY);
INSERT INTO {{schema}}.research_single_row VALUES (1);
CREATE TABLE {{schema}}.research_stale_pages(id bigint PRIMARY KEY, payload text) WITH (autovacuum_enabled=false);
INSERT INTO {{schema}}.research_stale_pages SELECT i, repeat('x', 250) FROM generate_series(1, 10000) i;
CREATE TABLE {{schema}}.research_extreme_keys(id bigint PRIMARY KEY);
INSERT INTO {{schema}}.research_extreme_keys VALUES (-9223372036854775808), (-9000000000000000000), (-1), (0), (1), (2), (9223372036854775807);
CREATE TABLE {{schema}}.research_nullable_keys(id bigint PRIMARY KEY, split_key integer);
INSERT INTO {{schema}}.research_nullable_keys SELECT i, CASE WHEN i % 7 = 0 THEN NULL ELSE i % 3 END FROM generate_series(1, 100) i;
CREATE TABLE {{schema}}.research_composite_keys(tenant text COLLATE "C", id bigint, PRIMARY KEY(tenant,id));
INSERT INTO {{schema}}.research_composite_keys SELECT tenant, i FROM unnest(ARRAY['', 'A', 'a', 'ab', 'z', 'é', 'я', '😀']) tenant CROSS JOIN generate_series(-2,2) i;
CREATE TABLE {{schema}}.research_key_moves(id bigint PRIMARY KEY, logical_id bigint UNIQUE NOT NULL);
INSERT INTO {{schema}}.research_key_moves SELECT i,i FROM generate_series(1,100) i;
CREATE TABLE {{schema}}.research_tid_moves(id bigint PRIMARY KEY, payload text) WITH(fillfactor=100, autovacuum_enabled=false);
ALTER TABLE {{schema}}.research_tid_moves ALTER COLUMN payload SET STORAGE PLAIN;
INSERT INTO {{schema}}.research_tid_moves SELECT i, repeat('x', 1800) FROM generate_series(1,300) i;
CREATE TABLE {{schema}}.research_growth(id bigint PRIMARY KEY, payload text) WITH(autovacuum_enabled=false);
ALTER TABLE {{schema}}.research_growth ALTER COLUMN payload SET STORAGE PLAIN;
INSERT INTO {{schema}}.research_growth SELECT i, repeat('x',1800) FROM generate_series(1,10) i;
CREATE TABLE {{schema}}.research_parted(part integer, id bigint, PRIMARY KEY(part,id)) PARTITION BY LIST(part);
CREATE TABLE {{schema}}.research_parted_a PARTITION OF {{schema}}.research_parted FOR VALUES IN (1);
CREATE TABLE {{schema}}.research_parted_b PARTITION OF {{schema}}.research_parted FOR VALUES IN (2);
INSERT INTO {{schema}}.research_parted SELECT part, i FROM generate_series(1,2) part CROSS JOIN generate_series(1,10) i;
CREATE TABLE {{schema}}.research_uuid_keys(row_id integer UNIQUE NOT NULL, k uuid PRIMARY KEY);
INSERT INTO {{schema}}.research_uuid_keys VALUES (1,'00000000-0000-0000-0000-000000000000'),(2,'00000000-0000-0000-0000-000000000001'),(3,'00000000-0000-0000-0000-ffffffffffff'),(4,'10000000-0000-0000-0000-000000000000'),(5,'80000000-0000-0000-0000-000000000000'),(6,'ffffffff-ffff-ffff-ffff-ffffffffffff');
CREATE TABLE {{schema}}.research_binary_keys(row_id integer UNIQUE NOT NULL, k bytea PRIMARY KEY);
INSERT INTO {{schema}}.research_binary_keys SELECT ord,decode(v,'hex') FROM unnest(ARRAY['','00','0000','0001','01','0100','7f','80','ff','ff00']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_date_keys(row_id integer UNIQUE NOT NULL, k date PRIMARY KEY);
INSERT INTO {{schema}}.research_date_keys SELECT ord,v::date FROM unnest(ARRAY['-infinity','0001-01-01 BC','0001-01-01 AD','1900-03-01','2000-02-29','9999-12-31','infinity']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_timestamp_keys(row_id integer UNIQUE NOT NULL, k timestamptz PRIMARY KEY);
INSERT INTO {{schema}}.research_timestamp_keys SELECT ord,v::timestamptz FROM unnest(ARRAY['-infinity','0001-01-01 00:00:00+00 BC','1969-12-31 23:59:59.999999+00','2024-03-31 01:59:59.999999+01','2024-03-31 03:00:00+02','2024-11-03 01:30:00-04','2024-11-03 01:30:00-05','infinity']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_decimal_keys(row_id integer UNIQUE NOT NULL, k numeric PRIMARY KEY);
INSERT INTO {{schema}}.research_decimal_keys SELECT ord,v::numeric FROM unnest(ARRAY['-100000000000000000000000000000000000000000000000000.1','-0.00000000000000000001','0','0.00000000000000000001','1.00000000000000000001','1.00000000000000000002','100000000000000000000000000000000000000000000000000.1']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_float_keys(row_id integer UNIQUE NOT NULL, k double precision PRIMARY KEY);
INSERT INTO {{schema}}.research_float_keys SELECT ord,v::double precision FROM unnest(ARRAY['-Infinity','-1','-0','1','Infinity','NaN']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_locale_keys(row_id integer UNIQUE NOT NULL, k text PRIMARY KEY);
INSERT INTO {{schema}}.research_locale_keys SELECT ord,v FROM unnest(ARRAY['','A','a','aa','z','ä','é','é','я','😀']) WITH ORDINALITY AS t(v,ord);
CREATE TABLE {{schema}}.research_mixed_composite(row_id integer UNIQUE NOT NULL, tenant text COLLATE "C", sequence numeric, happened timestamptz, PRIMARY KEY(tenant,sequence,happened));
INSERT INTO {{schema}}.research_mixed_composite SELECT row_number() OVER (),tenant,seq::numeric,stamp::timestamptz FROM unnest(ARRAY['','A','a','é','😀']) tenant CROSS JOIN unnest(ARRAY['-0.00000000000000000001','1.00000000000000000001','1.00000000000000000002']) seq CROSS JOIN unnest(ARRAY['2024-11-03 01:30:00-04','2024-11-03 01:30:00-05']) stamp;
CREATE TABLE {{schema}}.research_null_patterns(id integer PRIMARY KEY,a integer,b integer);
INSERT INTO {{schema}}.research_null_patterns SELECT i,CASE WHEN i%4=0 THEN NULL ELSE i%3 END,CASE WHEN i%5=0 THEN NULL ELSE i%2 END FROM generate_series(1,100) i;
CREATE TABLE {{schema}}.research_all_nulls(id integer PRIMARY KEY,k integer);
INSERT INTO {{schema}}.research_all_nulls SELECT i,NULL FROM generate_series(1,11) i;
CREATE TABLE {{schema}}.research_stats_missing(id integer PRIMARY KEY,k integer) WITH(autovacuum_enabled=false);
INSERT INTO {{schema}}.research_stats_missing SELECT i,i FROM generate_series(1,1000) i;
CREATE TABLE {{schema}}.research_stats_stale(row_id integer UNIQUE NOT NULL,k integer PRIMARY KEY) WITH(autovacuum_enabled=false);
INSERT INTO {{schema}}.research_stats_stale SELECT i,i FROM generate_series(1,1000) i;
CREATE TABLE {{schema}}.research_stats_mcv(id integer PRIMARY KEY,k integer NOT NULL) WITH(autovacuum_enabled=false);
INSERT INTO {{schema}}.research_stats_mcv SELECT i,CASE WHEN i<=9000 THEN 0 ELSE i-9000 END FROM generate_series(1,10000) i;
CREATE TABLE {{schema}}.research_wide_keys(row_id integer UNIQUE NOT NULL,k text PRIMARY KEY);
INSERT INTO {{schema}}.research_wide_keys SELECT i,repeat('x',1500)||lpad(i::text,6,'0') FROM generate_series(1,64) i;
CREATE TABLE {{schema}}.research_rls_keys(id integer PRIMARY KEY,row_id integer UNIQUE NOT NULL,k integer UNIQUE NOT NULL);
INSERT INTO {{schema}}.research_rls_keys SELECT i,i,i FROM generate_series(1,100) i;
CREATE TABLE {{schema}}.research_array_keys(row_id integer UNIQUE NOT NULL,k integer[] PRIMARY KEY);
INSERT INTO {{schema}}.research_array_keys SELECT ord,v::integer[] FROM unnest(ARRAY['{}','{-1}','{1}','{1,NULL}','{1,2}','[0:1]={1,2}','{2}','{2,1}','{NULL}']) WITH ORDINALITY AS t(v,ord);
CREATE TYPE {{schema}}.research_edge_priority AS ENUM('z_low','a_middle','m_high');
CREATE TABLE {{schema}}.research_enum_keys(row_id integer UNIQUE NOT NULL,k {{schema}}.research_edge_priority PRIMARY KEY);
INSERT INTO {{schema}}.research_enum_keys VALUES(1,'z_low'),(2,'a_middle'),(3,'m_high');
CREATE TABLE {{schema}}.research_attach_candidate(part integer NOT NULL,id bigint NOT NULL,PRIMARY KEY(part,id));
